<div class="section-heading"><div><span class="eyebrow">ADMINISTRAÇÃO</span><h1><?= e($title) ?><span class="accent">.</span></h1><p><?= count($rows) ?> registros encontrados</p></div><a class="btn" href="<?= e(url('admin/'.$entity.'/form')) ?>">+ Cadastrar</a></div><form class="admin-search" method="get"><input type="hidden" name="r" value="<?= e('admin/'.$entity) ?>"><label class="sr-only" for="q">Buscar registro</label><input id="q" name="q" maxlength="100" value="<?= e($q) ?>" placeholder="Buscar por nome, título ou e-mail"><button class="btn quiet">Buscar</button><a href="<?= e(url('admin/'.$entity)) ?>">Limpar</a></form><div class="table-wrap"><table><thead><tr><th>ID</th><?php if ($entity==='games'): ?><th>Jogo</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Situação</th><?php elseif ($entity==='categorias'): ?><th>Nome</th><th>Descrição</th><?php else: ?><th>Nome</th><th>E-mail</th><th><?= $entity==='clientes'?'Telefone':'Perfil' ?></th><th>Situação</th><?php endif; ?><th>Ações</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= e($row['id']) ?></td><?php if ($entity==='games'): ?><td><strong><?= e($row['titulo']) ?></strong><br><small><?= e($row['plataforma']) ?> · <?= e($row['sistemas']) ?></small></td><td><?= e($row['categoria']) ?></td><td class="nowrap"><?= money($row['preco']) ?></td><td><?= e($row['estoque']) ?></td><td><?= $row['ativo']?'Ativo':'Inativo' ?></td><?php elseif ($entity==='categorias'): ?><td><?= e($row['nome']) ?></td><td><?= e($row['descricao']) ?></td><?php else: ?><td><?= e($row['nome']) ?></td><td><?= e($row['email']) ?></td><td><?= e($row[$entity==='clientes'?'telefone':'perfil']) ?></td><td><?= $row['ativo']?'Ativo':'Inativo' ?></td><?php endif; ?><td><div class="actions"><a class="btn tiny quiet" href="<?= e(url('admin/'.$entity.'/form',['id'=>$row['id']])) ?>">Editar</a><form data-confirm="Excluir este registro?" method="post" action="<?= e(url('admin/'.$entity.'/delete')) ?>"><?= csrfField() ?><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="btn tiny danger">Excluir</button></form></div></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="8" class="empty">Nenhum registro encontrado.</td></tr><?php endif; ?></tbody></table></div>
